import {
  ChangeDetectionStrategy,
  Component,
  booleanAttribute,
  forwardRef,
  input,
  linkedSignal,
  model,
} from '@angular/core';
import { type ControlValueAccessor, NG_VALUE_ACCESSOR } from '@angular/forms';

export type AevkoToggleVariant = 'default' | 'outline';
export type AevkoToggleSize = 'sm' | 'md' | 'lg';

@Component({
  selector: 'button[aevkoToggle]',
  standalone: true,
  providers: [
    {
      provide: NG_VALUE_ACCESSOR,
      useExisting: forwardRef(() => AevkoToggle),
      multi: true,
    },
  ],
  template: '<ng-content />',
  styleUrl: './toggle.component.css',
  changeDetection: ChangeDetectionStrategy.OnPush,
  host: {
    'data-slot': 'toggle',
    type: 'button',
    '[attr.aria-pressed]': 'pressed()',
    '[attr.data-state]': 'pressed() ? "on" : "off"',
    '[attr.data-variant]': 'variant()',
    '[attr.data-size]': 'size()',
    '[disabled]': 'disabledState()',
    '(click)': 'toggle()',
    '(blur)': 'markTouched()',
  },
})
export class AevkoToggle implements ControlValueAccessor {
  readonly pressed = model(false);
  readonly disabled = input(false, { transform: booleanAttribute });
  readonly variant = input<AevkoToggleVariant>('default');
  readonly size = input<AevkoToggleSize>('md');
  protected readonly disabledState = linkedSignal(() => this.disabled());
  private onChange: (value: boolean) => void = () => undefined;
  private onTouched: () => void = () => undefined;

  protected toggle(): void {
    if (this.disabledState()) return;
    this.pressed.update((value) => !value);
    this.onChange(this.pressed());
    this.onTouched();
  }

  protected markTouched(): void {
    this.onTouched();
  }

  writeValue(value: boolean): void {
    this.pressed.set(Boolean(value));
  }

  registerOnChange(fn: (value: boolean) => void): void {
    this.onChange = fn;
  }

  registerOnTouched(fn: () => void): void {
    this.onTouched = fn;
  }

  setDisabledState(disabled: boolean): void {
    this.disabledState.set(disabled);
  }
}

:host {
  align-items: center;
  background: transparent;
  border: 1px solid transparent;
  border-radius: var(--aevko-radius, 0);
  color: var(--aevko-foreground, #09090b);
  cursor: pointer;
  display: inline-flex;
  font: 500 0.875rem/1 var(--aevko-font-sans, sans-serif);
  gap: 0.5rem;
  justify-content: center;
  min-width: 2.25rem;
  padding-inline: 0.75rem;
}

:host([data-size='sm']) {
  min-height: 2rem;
}
:host([data-size='md']) {
  min-height: 2.5rem;
}
:host([data-size='lg']) {
  min-height: 3rem;
  padding-inline: 1rem;
}
:host([data-variant='outline']) {
  border-color: var(--aevko-border, #e4e4e7);
}
:host([data-state='on']) {
  background: var(--aevko-foreground, #09090b);
  color: var(--aevko-background, #fff);
}
:host(:hover:not(:disabled)) {
  background: var(--aevko-surface, #f4f4f5);
  color: var(--aevko-foreground, #09090b);
}
:host(:focus-visible) {
  outline: 2px solid var(--aevko-focus, #a1a1aa);
  outline-offset: 1px;
}
:host(:disabled) {
  cursor: not-allowed;
  opacity: 0.5;
}
